create table wksp_dtesc.sgt_ceo_elementos (
    id             number generated by default as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by 1 cache 20 noorder
    nocycle nokeep noscale not null enable,
    fo_id          number,
    capacidad      number,
    ubicacion      varchar2(30 byte) not null enable,
    tipo_material  varchar2(20 byte) not null enable,
    lon            number(10, 7) not null enable,
    lat            number(10, 7) not null enable,
    tipo_elemento  number,
    reserva_mts    number,
    cod_columna    varchar2(255 byte),
    comentarios    clob,
    creado_por     varchar2(255 byte),
    creado_el      timestamp(6),
    modificado_por varchar2(255 byte),
    modificado_el  timestamp(6)
);

alter table wksp_dtesc.sgt_ceo_elementos
    add constraint ceo_pk primary key ( id )
        using index enable;

alter table wksp_dtesc.sgt_ceo_elementos
    add constraint chk_ceo_capacidad
        check ( capacidad in ( 12, 24, 36, 72, 144 ) ) disable;

alter table wksp_dtesc.sgt_ceo_elementos
    add constraint chk_ceo_tipo
        check ( tipo_material in ( 'Plástica', 'Metálica' ) ) enable;

alter table wksp_dtesc.sgt_ceo_elementos
    add constraint chk_ceo_ubicacion
        check ( ubicacion in ( 'Columna', 'Volante', 'Subterránea' ) ) enable;


